import { useCallback, useEffect, useRef, useState } from "react";
import { Bell, CheckCheck } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  ListNotifications,
  MarkAllNotificationsRead,
  MarkNotificationRead,
  UnreadNotifications,
} from "../../wailsjs/go/controllers/Notifications";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../wailsjs/runtime";
import { useT } from "../lib/i18n";

type Item = {
  id: string;
  kind: string;
  title: string;
  detail?: string;
  at: string;
  read: boolean;
};

// NotificationBell is the sidebar inbox: badge with the unread count, a
// dropdown with recent notices, mark-read and mark-all. New arrivals
// announce themselves through notifications:new.
export default function NotificationBell() {
  const t = useT();
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState<Item[]>([]);
  const [unread, setUnread] = useState(0);
  const boxRef = useRef<HTMLDivElement>(null);

  const refresh = useCallback(() => {
    ListNotifications()
      .then((list: Item[]) => setItems(list ?? []))
      .catch(() => {});
    UnreadNotifications()
      .then((n: number) => setUnread(n ?? 0))
      .catch(() => {});
  }, []);

  useEffect(() => {
    refresh();
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("notifications:new", () => refresh());
  }, [refresh]);

  // Close on outside click.
  useEffect(() => {
    if (!open) return;
    const onDown = (event: MouseEvent) => {
      if (boxRef.current && !boxRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    };
    window.addEventListener("mousedown", onDown);
    return () => window.removeEventListener("mousedown", onDown);
  }, [open]);

  const openItem = async (item: Item) => {
    if (!item.read) {
      await MarkNotificationRead(item.id).catch(() => {});
      refresh();
    }
  };

  return (
    <div ref={boxRef} className="relative px-2 pb-3">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        title={t("notifications.title")}
        className="relative flex h-8 w-8 items-center justify-center rounded-md border border-white/10 bg-white/5 text-white/60 hover:bg-white/10 hover:text-white"
      >
        <Bell className="h-4 w-4" />
        {unread > 0 && (
          <span className="absolute -right-1 -top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-accent px-1 text-[9px] font-semibold text-white">
            {unread > 99 ? "99+" : unread}
          </span>
        )}
      </button>
      {open && (
        <div className="absolute bottom-10 left-2 z-50 w-72 overflow-hidden rounded-lg border border-white/15 bg-[#141a2e]/95 shadow-2xl backdrop-blur">
          <div className="flex items-center justify-between border-b border-white/10 px-3 py-2">
            <span className="text-xs font-medium text-white/80">{t("notifications.title")}</span>
            <button
              type="button"
              onClick={() => void MarkAllNotificationsRead().then(refresh)}
              title={t("notifications.markAll")}
              className="rounded p-1 text-white/40 hover:bg-white/10 hover:text-white"
            >
              <CheckCheck className="h-3.5 w-3.5" />
            </button>
          </div>
          <div className="max-h-72 overflow-y-auto">
            {items.length === 0 ? (
              <p className="px-3 py-6 text-center text-xs text-white/40">{t("notifications.empty")}</p>
            ) : (
              items.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => void openItem(item)}
                  className="block w-full border-b border-white/5 px-3 py-2 text-left hover:bg-white/5"
                >
                  <div className="flex items-center gap-1.5">
                    {!item.read && <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-accent2" />}
                    <span className={`truncate text-xs ${item.read ? "text-white/50" : "font-medium text-white/85"}`}>
                      {item.title}
                    </span>
                  </div>
                  {item.detail && (
                    <p className="mt-0.5 line-clamp-2 text-[10px] leading-snug text-white/40">{item.detail}</p>
                  )}
                  <p className="mt-0.5 text-[9px] text-white/25">{new Date(item.at).toLocaleString()}</p>
                </button>
              ))
            )}
          </div>
        </div>
      )}
    </div>
  );
}
